import {uid,today,addDays,parseDate,dueLabel,groupDue,quickParse,newTask,newItem,completeTask,flattenChildren,checkChildren,CATEGORIES,defaultSettings,importMarkdown,exportMarkdown,calendarExport,validateRecord} from './core.js';
import {Store,credentials,saveCredentials,forgetCredentials,readLocal,writeLocal} from './store.js';
import {encryptSecret,decryptSecret} from './crypto.js';
import {createHousehold} from './household.js';
import {DEFAULT_REPO,DEFAULT_BRANCH} from './config.js';

const $=(s,root=document)=>root.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',tasks:'m4 6 2 2 4-4M13 6h7M4 13h4m5 0h7M4 20h4m5 0h7',shopping:'m3 3 2 2 2 11h11l3-9H6M9 21h.01M18 21h.01',calendar:'M4 5h16v16H4ZM4 10h16M8 3v4m8-4v4M8 14h2m4 0h2m-8 3h2',places:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0ZM9 10a3 3 0 1 0 6 0 3 3 0 1 0-6 0',vault:'M5 10h14v11H5ZM8 10V7a4 4 0 0 1 8 0v3m-4 5v2',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 1 0 0-8M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',plus:'M12 5v14M5 12h14',arrow:'M4 12h16m-6-6 6 6-6 6',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',search:'M10 3a7 7 0 1 0 0 14 7 7 0 1 0 0-14m5 12 6 6',more:'M5 12h.01M12 12h.01M19 12h.01',sun:'M12 7a5 5 0 1 0 0 10 5 5 0 1 0 0-10M12 2v1m0 18v1M2 12h1m18 0h1M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1',leaf:'M20 3C9 2 2 8 5 15s14 5 15-12ZM5 20l9-12',note:'M5 3h14v18H5ZM8 7h8M8 11h8M8 15h5',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',sync:'M20 7A9 9 0 0 0 4 6L2 9m0-6v6h6m-4 8a9 9 0 0 0 16 1l2-3m0 6v-6h-6',heart:'M12 21S2 15 2 8a5 5 0 0 1 10-1 5 5 0 0 1 10 1c0 7-10 13-10 13Z',key:'M9 14a6 6 0 1 1 4-4l9 9-3 3-3-3 1-2-2-2-2 1Z',logout:'M10 3H3v18h7m5-14 5 5-5 5M8 12h12',copy:'M8 8h13v13H8ZM16 8V3H3v13h5',pin:'m9 3 6 0v5l4 5H5l4-5Zm3 10v9',moon:'M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11Z'};
Object.assign(icons,{appointments:icons.calendar,damages:'M3 7h4l2-3h6l2 3h4v14H3ZM8 14a4 4 0 1 0 8 0 4 4 0 0 0-8 0',documents:'M5 3h9l5 5v13H5ZM14 3v6h5M8 13h8M8 17h6',upload:'M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5',train:'M6 3h12v14H6ZM6 10h12M9 14h.01M15 14h.01M8 17l-3 5m11-5 3 5M8 20h8',bus:'M4 4h16v15H4ZM4 12h16M8 16h.01M16 16h.01M7 19v3m10-3v3'});icons.camera=icons.damages;icons.document=icons.documents;
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="${icons[name]||icons.note}"/></svg>`;
const store=new Store(),nav=[['home','Overview'],['tasks','To-dos'],['shopping','Shopping'],['calendar','Planner'],['appointments','Appointments'],['damages','Flat gallery'],['documents','Documents'],['places','Places'],['vault','Key vault']];
let page=nav.some(n=>n[0]===location.hash.slice(1))?location.hash.slice(1):'home';
let filter={search:'',done:false,assignee:'all',sort:'due',tag:'all',list:'all',place:'all',favorites:false};
let showLogin=true,authError='',busy=false,installPrompt=null,updateWorker=null,selectedPlace='',mapAllowed=readLocal('mapConsent',false),calendarMonth=today().slice(0,7);
let vaultPass='',vaultTimer=null,toastTimer=null,undoAction=null,modalCleanup=null;
let theme=readLocal('theme','light');document.documentElement.dataset.theme=theme;
const money=n=>new Intl.NumberFormat(undefined,{style:'currency',currency:store.settings.currency}).format(n);
const person=id=>id==='both'?'Both of us':store.settings[id]||'Unassigned';
const initials=name=>(name||'?').split(/\s+/).map(p=>p[0]).slice(0,2).join('').toUpperCase();
const button=(label,action,cls='secondary',attrs='')=>`<button type="button" class="${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const empty=(title,description,action,label)=>`<div class="empty"><span class="empty-icon">${icon('leaf')}</span><h3>${title}</h3><p>${description}</p>${action&&store.canWrite?button(icon('plus')+label,action,'primary'):''}</div>`;
const avatar=id=>`<span class="avatar ${id==='person2'?'peach':id==='both'?'both':''}" title="${esc(person(id))}">${id==='both'?icon('heart'):esc(initials(person(id)))}</span>`;
function toast(message,undo=null){undoAction=undo;$('#toast').innerHTML=`<span>${esc(message)}</span>${undo?button('Undo','undo','text-button'):''}`;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),undo?10000:5000);}
function modal(title,content,wide=false){closeModal();const d=$('#modal');d.innerHTML=`<div class="modal-head"><h2 id="modal-title">${esc(title)}</h2>${button(icon('close'),'close','icon-button','aria-label="Close dialog"')}</div>${content}`;d.classList.toggle('wide',wide);d.showModal();d.querySelector('[autofocus]')?.focus();}
function closeModal(){if(modalCleanup){modalCleanup();modalCleanup=null;}const d=$('#modal');if(d.open)d.close();d.innerHTML='';}
$('#modal').addEventListener('cancel',e=>{e.preventDefault();closeModal();});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
function formError(error){const el=$('.form-error',$('#modal'))||$('.form-error');if(el)el.textContent=error.message||String(error);else toast(error.message||String(error));}
function setBusy(form,on){form.querySelectorAll('button[type="submit"]').forEach(b=>{b.disabled=on;b.classList.toggle('loading',on);});}
const input=(name,label,value='',type='text',attrs='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
const textarea=(name,label,value='',attrs='')=>`<label>${label}<textarea name="${name}" ${attrs}>${esc(value)}</textarea></label>`;
const select=(name,label,options,value)=>`<label>${label}<select name="${name}">${options.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;
const whoOptions=()=>[['both','Both of us'],['person1',store.settings.person1],['person2',store.settings.person2]];
const formFooter=(submit='Save',remove=false)=>`<p class="form-error" role="alert"></p><div class="modal-actions">${remove?button('Delete','delete-record','danger'):''}<span class="spacer"></span>${button('Cancel','close') }<button class="primary" type="submit">${submit}</button></div>`;

const household=createHousehold({store,$,esc,icon,button,heading,empty,input,textarea,select,whoOptions,modal,closeModal,formFooter,toast,render,person,avatar,taskRow,formError,confirmImport,setCleanup:fn=>modalCleanup=fn,search:()=>filter.search,assignee:()=>filter.assignee,page:()=>page,isLogin:()=>showLogin});

function loginView(){
  return `<main class="welcome welcome-simple">
    <a class="welcome-brand" href="#home"><img src="./icons/icon.svg" alt="" width="40" height="40"><span>together<span class="brand-dot">.</span></span></a>
    <section class="connect-card"><span class="welcome-mark">${icon('home')}</span><h1>Your shared home.</h1><p>One place for your plans, lists and documents.</p>
      <form id="connect-form"><div class="form-row">${input('repo','Private repository',credentials()?.repo||DEFAULT_REPO,'text','required placeholder="owner/partner-data" autocapitalize="off" spellcheck="false"')}${input('branch','Branch',credentials()?.branch||DEFAULT_BRANCH,'text','required autocapitalize="off" spellcheck="false"')}</div>
      ${input('label','Connection name',credentials()?.label||'','text','required maxlength="80" placeholder="Matthias’s phone"')}
      ${input('token','GitHub token','','password','required placeholder="github_pat_…" autocomplete="off" autocapitalize="off" spellcheck="false"')}
      <label class="check-label"><input name="remember" type="checkbox"> Remember token on this device</label>
      <label class="check-label"><input name="readOnly" type="checkbox" ${credentials()?.readOnly?'checked':''}> Read-only access</label>
      <p class="form-error" role="alert">${esc(authError)}</p><button class="primary full" type="submit">Open our space ${icon('arrow')}</button></form>
      ${store.pending.length?`<div class="notice">${store.pending.length} unsynced changes on this device.<div class="button-row">${button('Export backup','export-backup','text-button')}${button('Forget connection','logout','text-button')}</div></div>`:''}
      <div class="login-options">${button('Try demo','demo','text-button')}${button('Setup guide','github-help','text-button')}</div>
      <p class="login-privacy">${icon('vault')} Your data stays in your private repository.</p>
    </section></main>`;
}
function statusView(){const names={synced:'All changes saved',syncing:'Syncing…',offline:'Offline · saved on this device',conflict:'An edit needs your attention',error:'Sync needs attention',demo:'Demo · on this device',locked:'Access key needs updating',disconnected:'Not connected',secondary:'Open in another tab'};return `<button class="sync-status ${store.state}" data-action="sync" title="${esc(store.error||'Sync now')}"><span class="status-dot"></span>${names[store.state]||store.state}${store.pending.length?` · ${store.pending.length} waiting`:''}</button>`;}
function render(){
  if(showLogin){$('#app').innerHTML=loginView();return;}
  const focused=document.activeElement?.id,selection=focused==='search'?document.activeElement.selectionStart:null;
  const taskCount=store.list('task').filter(r=>!r.data.done).length,itemCount=store.list('item').filter(r=>!r.data.done).length;
  const active=id=>page===id||(id==='calendar'&&page==='appointments');
  const navigation=ids=>ids.map(id=>{const label=nav.find(n=>n[0]===id)[1],count=id==='tasks'?taskCount:id==='shopping'?itemCount:0;return `<a href="#${id}" class="nav-link ${active(id)?'active':''}" ${active(id)?'aria-current="page"':''}>${icon(id)}<span>${label}</span>${count?`<b>${count}</b>`:''}</a>`;}).join('');
  const mobile=[['home','Home'],['tasks','To-dos'],['shopping','Shopping'],['calendar','Planner'],['more','Browse']];
  $('#app').innerHTML=`<div class="shell"><aside class="sidebar">
    <a class="brand" href="#home"><img src="./icons/icon.svg" alt="" width="36" height="36">together<span class="brand-dot">.</span></a>
    <div class="household-label"><span class="eyebrow">SHARED SPACE</span><strong>${esc(store.settings.title)}</strong></div>
    <nav aria-label="Main navigation"><div class="nav-group"><span class="nav-caption">Everyday</span>${navigation(['home','tasks','shopping','calendar'])}</div><div class="nav-group"><span class="nav-caption">Home & files</span>${navigation(['documents','damages','places','vault'])}</div></nav>
    <div class="sidebar-bottom"><a href="#settings" class="nav-link ${page==='settings'?'active':''}" ${page==='settings'?'aria-current="page"':''}>${icon('settings')}<span>Settings</span></a><div class="people">${avatar('person1')}${avatar('person2')}<div><strong>${esc(store.settings.person1)} & ${esc(store.settings.person2)}</strong></div></div></div>
    </aside><div class="workspace"><header class="topbar"><a href="#home" class="workspace-name">${icon('home')}<span>${esc(store.settings.title)}</span></a><div class="topbar-right">${statusView()}${button(icon(theme==='dark'?'sun':'moon'),'theme','icon-button','aria-label="Toggle color theme"')}</div></header>
    ${store.demo?`<div class="demo-banner"><span class="demo-label">Demo</span>${button('Connect your household','connect','text-button')}</div>`:''}
    ${store.state==='secondary'?'<div class="notice">Read-only in this tab. Close the other tab and reload to edit.</div>':''}
    ${store.state==='offline'?'<div class="notice">Offline. Edits sync when connected; files and journeys need internet.</div>':''}
    ${store.state==='error'?`<div class="notice error">${esc(store.error)} ${button('Retry sync','sync','text-button')}</div>`:''}
    ${store.conflict?conflictView():''}${updateWorker?`<div class="notice">Update available. ${button('Update app','update','text-button')}</div>`:''}
    <main id="main" tabindex="-1">${({home:homeView,tasks:tasksView,shopping:shoppingView,calendar:calendarView,places:placesView,vault:vaultView,settings:settingsView,...household.views}[page]||homeView)()}</main></div>
    <nav class="mobile-nav" aria-label="Mobile navigation">${mobile.map(([id,label])=>{const selected=id==='more'?!['home','tasks','shopping','calendar','appointments'].includes(page):active(id);return `<button data-action="${id==='more'?'more':'nav'}" data-page="${id}" class="${selected?'active':''}" ${selected?'aria-current="page"':''} ${id==='more'?'aria-haspopup="dialog"':''}>${icon(id)}<span>${label}</span></button>`;}).join('')}</nav></div>`;
  household.afterRender();
  if(focused==='search'){$('#search')?.focus();$('#search')?.setSelectionRange(selection,selection);}
}
function conflictView(){const c=store.conflict;return `<section class="conflict" role="alert"><strong>Two edits, one ${esc(c.op.kind)}.</strong><p>“${esc(c.op.data?.title||'Deleted item')}” changed on another device. Your edit is safely waiting here.</p><div>${button('Compare edits','compare-conflict','secondary')}${button('Use their version','use-theirs','secondary')}${button('Keep my version','keep-mine','primary')}</div></section>`;}
function heading(eyebrow,title,description,action='',label=''){return `<div class="page-heading"><div>${eyebrow?`<span class="eyebrow">${eyebrow}</span>`:''}<h1>${title}</h1>${description?`<p>${description}</p>`:''}</div>${action&&store.canWrite?button(icon('plus')+`<span>${label}</span>`,action,'primary',`aria-label="${esc(label)}"`):''}</div>`;}
function taskRow(r,compact=false){const t=r.data,children=flattenChildren(t.children||[]),done=children.filter(c=>c.done).length;return `<div class="task-row ${t.done?'completed':''}"><button class="round-check priority-${t.priority} ${t.done?'checked':''}" data-action="toggle-task" data-id="${r.id}" aria-label="${t.done?'Reopen':'Complete'} ${esc(t.title)}" ${!store.canWrite?'disabled':''}>${t.done?icon('check'):''}</button><button class="row-content" data-action="edit-task" data-id="${r.id}"><strong>${esc(t.title)}</strong><span class="row-meta">${t.tags.map(l=>`<span class="tag">${esc(l)}</span>`).join('')}${children.length?`<span>${done}/${children.length} steps</span>`:''}${t.repeat?`<span>${icon('sync')} ${t.repeat}</span>`:''}</span></button><span class="due ${t.due&&t.due<today()&&!t.done?'overdue':''} ${t.due===today()?'today':''}">${t.due?dueLabel(t.due):compact?'':'Anytime'}</span>${avatar(t.assignee)}</div>`;}
function itemRow(r,compact=false){const t=r.data,p=store.get(t.placeId);return `<div class="task-row shopping-row ${t.done?'completed':''}"><button class="round-check ${t.done?'checked':''}" data-action="toggle-item" data-id="${r.id}" aria-label="${t.done?'Uncheck':'Buy'} ${esc(t.title)}" ${!store.canWrite?'disabled':''}>${t.done?icon('check'):''}</button><button class="row-content" data-action="edit-item" data-id="${r.id}"><strong>${esc(t.title)} ${t.favorite?'<span class="favorite-star">★</span>':''}</strong><span class="row-meta"><span>${esc(t.quantity)} ${esc(t.unit)}</span>${!compact&&p?`<span>${icon('places')}${esc(p.data.title)}</span>`:''}${t.due?`<span class="${t.due<today()&&!t.done?'overdue':''}">${dueLabel(t.due)}</span>`:''}</span></button>${t.price?`<span class="price">${money(t.price*t.quantity)}</span>`:''}${!compact?avatar(t.assignee):''}</div>`;}
function homeView(){
  const open=store.list('task').filter(r=>!r.data.done),shopping=store.list('item').filter(r=>!r.data.done),due=open.filter(r=>r.data.due&&r.data.due<=today());
  const notes=store.list('note').sort((a,b)=>Number(b.data.pinned)-Number(a.data.pinned));
  const date=new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric',timeZone:'Europe/Berlin'});
  return `${heading(date,'Overview','','quick-create','Add')}
    <div class="overview-stats">${[['tasks','To-dos',open.length,'sage'],['shopping','To buy',shopping.length,'peach-bg'],['calendar','Due now',due.length,'lilac']].map(([route,label,count,color])=>`<a href="#${route}" class="overview-stat"><span class="stat-icon ${color}">${icon(route)}</span><div><span>${label}</span><strong>${count}</strong></div>${icon('arrow')}</a>`).join('')}</div>
    <nav class="home-shortcuts" aria-label="Household shortcuts">${[['documents','Documents',store.list('document').length+' saved'],['damages','Flat gallery',store.list('damage').length+' record'+(store.list('damage').length===1?'':'s')],['vault','Key vault',store.list('secret').length+' key'+(store.list('secret').length===1?'':'s')]].map(([route,label,count])=>`<a href="#${route}"><span class="shortcut-icon">${icon(route)}</span><span><strong>${label}</strong><small>${count}</small></span>${icon('arrow')}</a>`).join('')}</nav>
    ${household.dashboard()}
    <div class="dashboard-grid home-bottom"><section class="panel"><div class="section-heading"><h2>Shopping <span class="tag">${shopping.length}</span></h2><a href="#shopping">View list ${icon('arrow')}</a></div>${shopping.length?shopping.slice(0,3).map(r=>itemRow(r,true)).join(''):'<p class="compact-empty">Nothing to buy.</p>'}<div class="panel-foot"><span>Estimated total</span><strong>${money(shopping.reduce((sum,r)=>sum+r.data.price*r.data.quantity,0))}</strong></div></section>
    <section class="panel notes-panel"><div class="section-heading"><h2>Notes</h2>${store.canWrite?button(icon('plus')+'Add note','new-note','text-button'):''}</div><div class="note-grid">${notes.length?notes.slice(0,2).map(r=>`<button class="note-card" data-action="edit-note" data-id="${r.id}"><span>${r.data.pinned?icon('pin'):icon('note')}</span><h3>${esc(r.data.title)}</h3><p>${esc(r.data.body)}</p></button>`).join(''):'<p class="compact-empty">No notes yet.</p>'}</div>${notes.length>2?button(`All ${notes.length} notes`,'all-notes','text-button all-notes-link'):''}</section></div>
    <details class="activity-details"><summary>${icon('sync')} Recent activity</summary><div class="activity-list">${store.activity.length?store.activity.slice(0,5).map(a=>`<div class="activity-row"><span class="activity-dot"></span><div><strong>${esc(a.actor)}</strong><p>${esc(a.message)}</p><small>${new Date(a.created_at).toLocaleString(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})}</small></div></div>`).join(''):'<p class="compact-empty">No activity yet.</p>'}</div></details>`;
}
function filterBar(kind){const tags=[...new Set(store.list('task').flatMap(t=>t.data.tags))].sort();return `<div class="filter-bar"><div class="search-field">${icon('search')}<input id="search" aria-label="Search ${kind}" placeholder="Search ${kind}…" value="${esc(filter.search)}"><kbd>/</kbd></div><select data-filter="assignee" aria-label="Filter by person">${[['all','Everyone'],...whoOptions()].map(([v,l])=>`<option value="${v}" ${filter.assignee===v?'selected':''}>${esc(l)}</option>`).join('')}</select>${kind==='to-dos'?`<select data-filter="sort" aria-label="Sort to-dos">${[['due','By due date'],['priority','By priority'],['tag','By label'],['created','Recently updated']].map(([v,l])=>`<option value="${v}" ${filter.sort===v?'selected':''}>${l}</option>`).join('')}</select><select data-filter="tag" aria-label="Filter by label"><option value="all">All labels</option>${tags.map(t=>`<option ${filter.tag===t?'selected':''}>${esc(t)}</option>`).join('')}</select>`:''}<label class="check-label"><input type="checkbox" data-filter="done" ${filter.done?'checked':''}> Show ${kind==='to-dos'?'done':'bought'}</label></div>`;}
function matches(r,includeDone=false){const d=r.data;return (includeDone===true||filter.done||!d.done)&&(filter.assignee==='all'||d.assignee===filter.assignee||(['person1','person2'].includes(filter.assignee)&&d.assignee==='both'))&&(!filter.search||JSON.stringify(d).toLowerCase().includes(filter.search.toLowerCase()));}
function tasksView(){
  const tasks=store.list('task').filter(matches).filter(r=>filter.tag==='all'||r.data.tags.includes(filter.tag)),groups=new Map();
  const priorities=['No priority','High priority','Medium priority','Low priority'];
  tasks.sort((a,b)=>a.data.done-b.data.done || (filter.sort==='priority'?(a.data.priority||4)-(b.data.priority||4):filter.sort==='created'?b.updated_at.localeCompare(a.updated_at):filter.sort==='tag'?(a.data.tags[0]||'~').localeCompare(b.data.tags[0]||'~'):(a.data.due||'9999').localeCompare(b.data.due||'9999')));
  for(const t of tasks){const g=t.data.done?'Done':filter.sort==='priority'?priorities[t.data.priority]:filter.sort==='tag'?(t.data.tags[0]||'No label'):filter.sort==='created'?'Our to-dos':groupDue(t.data.due);if(!groups.has(g))groups.set(g,[]);groups.get(g).push(t);}
  return `${heading('','To-dos','','new-task','Add a to-do')}<form id="quick-task" class="quick-add">${icon('plus')}<input name="title" required maxlength="500" aria-label="Quick add to-do" placeholder="Add a to-do…"><button class="primary" type="submit">Add</button></form>${filterBar('to-dos')}${tasks.length?[...groups].map(([g,rows])=>`<section class="task-group"><div class="group-heading"><h2>${esc(g)}</h2><span>${rows.length}</span></div><div class="panel task-list">${rows.map(t=>taskRow(t)).join('')}</div></section>`).join(''):empty('No to-dos','Add one above or adjust your filters.')}<div class="bottom-tools">${button(icon('download')+'Export Markdown','export-md','text-button')}${button('Import todo.md','import-md','text-button')}<span>Quick entry: !1 priority · @tomorrow · :label:</span></div>`;
}
function shoppingMatches(r,includeDone=false){return matches(r,includeDone)&&(filter.list==='all'||r.data.list===filter.list)&&(filter.place==='all'||r.data.placeId===filter.place)&&(!filter.favorites||r.data.favorite);}
let shoppingSelection=null;
function chooseBoughtItems(){
  if(!store.canWrite)throw new Error('This connection is read-only.');
  const rows=store.list('item').filter(r=>r.data.done&&shoppingMatches(r,true));
  if(!rows.length)return toast('No bought items match these filters.');
  const groups=[...new Set(rows.map(r=>r.data.list))];
  modal('Choose items to buy again',`<form id="repick-form"><p class="muted">Only selected items return to your shopping list.</p><div class="repick-items">${groups.map(list=>`<section><h3>${esc(list)}</h3>${rows.filter(r=>r.data.list===list).map(r=>`<label class="repick-item"><input type="checkbox" name="item" value="${r.id}"><span><strong>${esc(r.data.title)}</strong><small>${esc(r.data.quantity)} ${esc(r.data.unit)}${r.data.placeId?' · '+esc(store.get(r.data.placeId)?.data.title||'Saved shop'):''}</small></span></label>`).join('')}</section>`).join('')}</div><p id="repick-count" class="fine" role="status">0 selected</p><p class="form-error" role="alert"></p><div class="modal-actions">${button('Cancel','close')}<button class="primary" type="submit" disabled>Uncheck selected</button></div></form>`);
  shoppingSelection={ids:new Set(rows.map(r=>r.id)),generation:store.generation};modalCleanup=()=>shoppingSelection=null;
}
function shoppingView(){
  const all=store.list('item'),lists=[...new Set(['Groceries',...all.map(r=>r.data.list)])];
  const rows=all.filter(r=>shoppingMatches(r));
  const open=rows.filter(r=>!r.data.done),total=open.reduce((s,r)=>s+r.data.price*r.data.quantity,0),bought=rows.filter(r=>r.data.done),budget=store.settings.budget;
  const groups=[...CATEGORIES,'Bought'].map(cat=>[cat,rows.filter(r=>cat==='Bought'?r.data.done:!r.data.done&&r.data.category===cat)]).filter(([,rs])=>rs.length);
  return `${heading('','Shopping','','new-item','Add an item')}<div class="shopping-summary"><div><span class="eyebrow">ESTIMATED TOTAL</span><h2>${money(total)} <small>/ ${money(budget)} budget</small></h2><progress value="${Math.min(total,budget)}" max="${budget||1}" aria-label="Basket budget"></progress><p>${open.length} to pick up · ${bought.length} bought${total>budget?' · over budget':''}</p></div><span class="basket-art">${icon('shopping')}</span></div><div class="list-tabs">${[['all','All lists'],...lists.map(l=>[l,l])].map(([v,l])=>button(esc(l),'shopping-list',filter.list===v?'pill active':'pill',`data-list="${esc(v)}"`)).join('')}</div><form id="quick-item" class="quick-add">${icon('plus')}<input name="title" required maxlength="200" aria-label="Quick add shopping item" placeholder="Add an item…"><button class="primary" type="submit">Add</button></form>${filterBar('shopping')}<div class="secondary-filters"><select data-filter="place" aria-label="Filter by pickup place"><option value="all">All pickup places</option><option value="" ${filter.place===''?'selected':''}>No place assigned</option>${store.list('place').map(r=>`<option value="${r.id}" ${filter.place===r.id?'selected':''}>${esc(r.data.title)}</option>`).join('')}</select><label class="check-label"><input type="checkbox" data-filter="favorites" ${filter.favorites?'checked':''}> Favourites only</label>${button('Copy list','copy-shopping','text-button')}${store.canWrite?button('Uncheck bought items…','reset-shopping','text-button'):''}</div>${groups.length?groups.map(([name,rs])=>`<section class="task-group"><div class="group-heading"><h2>${name}</h2><span>${rs.length}</span></div><div class="panel">${rs.map(r=>itemRow(r)).join('')}</div></section>`).join(''):empty('No items','Add one above or adjust your filters.')}`;
}

function calendarView(){
  const first=parseDate(calendarMonth+'-01'),start=addDays(calendarMonth+'-01',-((first.getDay()+6)%7)),events=store.records.filter(r=>r.kind==='appointment'?r.data.status!=='cancelled':['task','item'].includes(r.kind)&&r.data.due&&!r.data.done);
  const cells=Array.from({length:42},(_,i)=>{const date=addDays(start,i),rs=events.filter(r=>r.kind==='appointment'?household.appointmentOnDate(r.data,date):r.data.due===date);return `<div class="calendar-cell ${date.slice(0,7)!==calendarMonth?'other-month':''} ${date===today()?'is-today':''}"><span class="day-number">${parseDate(date).getDate()}</span>${rs.slice(0,3).map(r=>`<button class="calendar-event ${r.kind}" data-action="edit-${r.kind}" data-id="${r.id}">${r.kind==='item'?icon('shopping'):''}${esc(r.data.title)}</button>`).join('')}${rs.length>3?button(`+${rs.length-3} more`,'day-events','text-button',`data-date="${date}"`):''}</div>`;});
  const eventDate=r=>r.kind==='appointment'?r.data.start:r.data.due;const upcoming=events.filter(r=>(r.kind==='appointment'?r.data.end:r.data.due)>=today()).sort((a,b)=>eventDate(a).localeCompare(eventDate(b)));
  return `${heading('','Planner','','new-appointment','Add appointment')}<nav class="view-switch" aria-label="Planner views"><a href="#calendar" aria-current="page">${icon('calendar')}Month</a><a href="#appointments">${icon('appointments')}Appointments</a></nav><div class="calendar-toolbar"><h2>${first.toLocaleDateString(undefined,{month:'long',year:'numeric'})}</h2><div>${button('‹','prev-month','icon-button','aria-label="Previous month"')}${button('Today','today-month')}${button('›','next-month','icon-button','aria-label="Next month"')}${button(icon('download')+'Calendar file','export-calendar','secondary')}</div></div><section class="calendar-grid" aria-label="Monthly calendar">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<span class="weekday">${d}</span>`).join('')}${cells.join('')}</section><div class="section-heading upcoming-heading"><h2>Coming up</h2><span>${upcoming.length} open plans</span></div><div class="panel">${upcoming.length?upcoming.slice(0,10).map(r=>r.kind==='appointment'?household.appointmentRow(r):r.kind==='task'?taskRow(r):itemRow(r)).join(''):empty('No upcoming plans','')}</div><p class="fine">Export to your calendar for reminders.</p>`;
}
function placesView(){
  const places=store.list('place');if(!places.some(r=>r.id===selectedPlace))selectedPlace=places[0]?.id||'';
  const selected=store.get(selectedPlace),p=selected?.data,hasCoords=p?.lat!==null&&p?.lat!==undefined;
  let map='';
  if(hasCoords&&mapAllowed){const bbox=[Math.max(-180,p.lon-.012),Math.max(-90,p.lat-.008),Math.min(180,p.lon+.012),Math.min(90,p.lat+.008)].join(',');map=`<iframe title="OpenStreetMap: ${esc(p.title)}" src="https://www.openstreetmap.org/export/embed.html?bbox=${encodeURIComponent(bbox)}&layer=mapnik&marker=${p.lat}%2C${p.lon}" loading="lazy" referrerpolicy="strict-origin-when-cross-origin"></iframe>`;}
  else map=`<div class="map-placeholder">${icon('places')}<h3>${hasCoords?'View on the map':'No location selected'}</h3><p>${hasCoords?'Load OpenStreetMap to see this place. Your IP address and the map area are shared with OpenStreetMap.':'Save a place with coordinates, or use your current location when adding one.'}</p>${hasCoords?button('Load OpenStreetMap','allow-map','primary'):button(icon('plus')+'Add a place','new-place','primary')}</div>`;
  return `${heading('','Places','','new-place','Save a place')}<div class="places-layout"><div class="places-list">${places.length?places.map(r=>`<button class="place-card ${r.id===selectedPlace?'selected':''}" data-action="select-place" data-id="${r.id}"><span class="place-marker">${icon('places')}</span><div><h3>${esc(r.data.title)}</h3><p>${esc(r.data.address||'No address yet')}</p><small>${store.list('item').filter(i=>i.data.placeId===r.id&&!i.data.done).length} items to pick up</small></div></button>`).join(''):empty('No saved places','Add a shop or pickup location.')}<p class="fine">Map data © OpenStreetMap contributors. Maps need a connection.${mapAllowed?' '+button('Turn maps off','disable-map','text-button'):''}</p></div><section class="map-panel">${map}${p?`<div class="place-details"><div><h2>${esc(p.title)}</h2><p>${esc(p.address)}</p><p class="prewrap">${esc(p.notes)}</p></div><div class="place-actions">${button('Edit place','edit-place','secondary',`data-id="${selected.id}"`)}<a class="primary" target="_blank" rel="noopener noreferrer" href="https://www.openstreetmap.org/${hasCoords?`?mlat=${p.lat}&mlon=${p.lon}#map=17/${p.lat}/${p.lon}`:`search?query=${encodeURIComponent(p.address||p.title)}`}">Open map ${icon('arrow')}</a></div></div>`:''}</section></div>`;
}
function vaultView(){const secrets=store.list('secret');return `${heading('','Key vault','',vaultPass?'new-secret':'','Save a key')}<div class="vault-explainer"><span class="stat-icon sage">${icon('vault')}</span><div><h3>${vaultPass?'Vault unlocked':'Vault locked'}</h3><p>Use your shared vault passphrase. Names are visible; values and notes are encrypted. A forgotten passphrase cannot be recovered.</p></div>${button(vaultPass?'Lock vault':'Unlock vault',vaultPass?'lock-vault':'unlock-vault','secondary')}</div>${secrets.length?`<div class="vault-grid">${secrets.map(r=>`<article class="vault-card"><span class="key-icon">${icon('key')}</span><div><h3>${esc(r.data.title)}</h3><p class="secret-mask">•••• •••• •••• ••••</p><small>Encrypted</small></div>${button(vaultPass?'Open':'Unlock',vaultPass?'edit-secret':'unlock-vault','secondary',`data-id="${r.id}"`)}</article>`).join('')}</div>`:empty('No saved keys','Unlock to add a service key.',vaultPass?'new-secret':'unlock-vault',vaultPass?'Save a key':'Create a vault passphrase')}<div class="info-note">${icon('key')}<p>App access tokens are managed in <a href="#settings">Settings & access</a>.</p></div><p class="fine">The vault locks after 5 minutes without activity and when you leave the app. Decrypted values are never written to browser storage.</p>`;}
function settingsView(){const s=store.settings;return `${heading('','Settings','')}<div class="settings-grid"><section class="panel settings-panel"><h2>Our household</h2><form id="household-form"><fieldset ${!store.canWrite?'disabled':''}>${input('title','Name of our space',s.title,'text','required maxlength="80"')}<div class="form-row">${input('person1','First person',s.person1,'text','required maxlength="40"')}${input('person2','Second person',s.person2,'text','required maxlength="40"')}</div><div class="form-row">${select('currency','Currency',[['EUR','EUR · Euro'],['USD','USD · US Dollar'],['GBP','GBP · Pound'],['CHF','CHF · Swiss Franc'],['CAD','CAD · Canadian Dollar'],['AUD','AUD · Australian Dollar'],['JPY','JPY · Yen']],s.currency)}${input('budget','Shopping budget',s.budget,'number','min="0" max="1000000" step="0.01" required')}</div><p class="form-error" role="alert"></p><button class="primary" type="submit">Save our settings</button></fieldset></form></section><section class="panel settings-panel"><h2>This device</h2><dl class="device-info"><dt>Connection name</dt><dd>${esc(store.key?.name||'Demo')}</dd><dt>Private repository</dt><dd>${store.config?`<a href="https://github.com/${esc(store.config.repo)}" target="_blank" rel="noopener noreferrer">${esc(store.config.repo)} ↗</a>`:'Demo · on this device'}</dd><dt>Branch</dt><dd>${esc(store.config?.branch||'—')}</dd><dt>Editing</dt><dd>${store.canWrite?'Enabled · GitHub checks token permissions':'Read-only'}</dd><dt>Sync</dt><dd>${statusView()}</dd><dt>Waiting edits</dt><dd>${store.pending.length}</dd></dl><div class="button-stack">${button(icon('download')+'Install on this device','install','secondary')}${button('Sync now','sync','secondary')}${button('Change connection / token','connect','secondary')}${button(icon('logout')+(store.demo?'Leave demo':'Lock & forget this device'),'logout','danger')}</div><p class="fine">Tokens are sent only to GitHub.</p></section></div><details class="panel settings-panel settings-details"><summary>Access & GitHub tokens</summary><div class="details-content"><p class="muted">Create a separate fine-grained token for each person or device, restricted to your private data repository with Contents: Read and write. GitHub manages token names, expiry and revocation.</p><div class="button-row"><a class="primary" href="https://github.com/settings/personal-access-tokens/new" target="_blank" rel="noopener noreferrer">Create token on GitHub ↗</a><a class="secondary" href="https://github.com/settings/personal-access-tokens" target="_blank" rel="noopener noreferrer">Manage / revoke tokens ↗</a>${button('Setup instructions','github-help','secondary')}</div><p class="fine">GitHub permissions protect the whole repository. Both editing tokens can change its files. Revocation blocks future requests; previously downloaded files and offline copies remain on that device.</p></div></details><div class="settings-grid"><section class="panel settings-panel"><h2>Backups</h2><p class="muted">Include stored files with a ZIP backup.</p><div class="button-stack">${button(icon('download')+'Backup with files (.zip)','export-file-backup','secondary')}${button('Restore backup with files (.zip)','import-file-backup','secondary')}${button(icon('download')+'Export records only (.json)','export-backup','secondary')}${button('Import household backup','import-backup','secondary')}${button('Import todo.md','import-md','secondary')}${button('Export to calendar (.ics)','export-calendar','secondary')}</div><p class="fine">ZIP: records + files, up to 100 MB. JSON: records only. Store backups privately; vault entries still need your passphrase.</p></section><details class="panel settings-panel settings-details"><summary>Shortcuts & help</summary><div class="details-content"><div class="help-item"><strong>Quick to-do syntax</strong><p><code>Book dinner !2 @fri :together:</code><br>Use !1–!3, @today, @tomorrow, @+3, @+2w, and labels.</p></div><div class="help-item"><strong>Keyboard shortcuts</strong><p><kbd>N</kbd> add in the current view · <kbd>/</kbd> search · <kbd>Esc</kbd> close a dialog</p></div><div class="help-item"><strong>Two people editing together</strong><p>Changes sync every minute while the app is open, and when you return. Conflicts wait for you to pick a version.</p></div><div class="help-item"><strong>Recurring to-dos</strong><p>Completing one advances its due date by one interval and resets its subtasks. It stays open for next time.</p></div></div></details></div>`;}

let editing=null;
function taskEditor(id){
  const record=id?store.get(id):null;if(id&&!record)return toast('This to-do is no longer available.');
  editing={kind:'task',id:id||uid(),data:structuredClone(record?.data||newTask())};
  const t=editing.data;
  modal(id?'A little more detail':'Add a to-do',`<form id="task-form"><fieldset ${!store.canWrite?'disabled':''}>${input('title','What needs doing?',t.title,'text','required maxlength="500" autofocus placeholder="A title, or quick syntax like !2 @fri :home:"')}<div class="form-row">${input('due','Due date',t.due,'date')}${select('priority','Priority',[[0,'No priority'],[1,'High'],[2,'Medium'],[3,'Low']],t.priority)}</div><div class="form-row">${select('assignee','Who’s on it?',whoOptions(),t.assignee)}${select('repeat','Repeat',[['','Doesn’t repeat'],['daily','Daily'],['weekly','Weekly'],['monthly','Monthly']],t.repeat)}</div>${input('tags','Labels (comma separated)',t.tags.join(', '),'text','placeholder="home, together" maxlength="800"')}${textarea('notes','Notes',t.notes,'rows="3" maxlength="10000"')}${input('link','Related link',t.link,'url','placeholder="https://…" maxlength="2000"')}<div class="subtask-heading"><strong>Small steps</strong><small>Nested subtasks are supported</small></div><div id="subtasks">${subtasksHTML(t.children)}</div><div class="subtask-add"><input id="subtask-title" placeholder="Add a small step…" aria-label="New subtask" maxlength="200">${button(icon('plus'),'add-subtask','secondary','aria-label="Add subtask"')}</div></fieldset>${store.canWrite?formFooter(id?'Save changes':'Add to-do',!!id):button('Close','close','secondary')}</form>`);
}
function subtasksHTML(children,depth=0){return children.map(c=>`<div class="subtask-wrap depth-${Math.min(depth,5)}"><div class="subtask-row"><input type="checkbox" data-subtask="${c.id}" ${c.done?'checked':''} aria-label="Complete ${esc(c.title)}"><input value="${esc(c.title)}" data-subtitle="${c.id}" maxlength="200" required aria-label="Subtask title">${button(icon('plus'),'nested-subtask','icon-button',`data-id="${c.id}" aria-label="Add nested subtask"`)}${button(icon('close'),'remove-subtask','icon-button',`data-id="${c.id}" aria-label="Remove subtask"`)}</div>${subtasksHTML(c.children||[],depth+1)}</div>`).join('');}
function itemEditor(id){
  const record=id?store.get(id):null;if(id&&!record)return toast('This item is no longer available.');
  const t=structuredClone(record?.data||{...newItem(),list:filter.list==='all'?'Groceries':filter.list});editing={kind:'item',id:id||uid(),data:t};
  const lists=[...new Set(['Groceries',...store.list('item').map(r=>r.data.list)])];
  modal(id?'Shopping details':'Add to our basket',`<form id="item-form"><fieldset ${!store.canWrite?'disabled':''}>${input('title','What do we need?',t.title,'text','required maxlength="200" autofocus')}<div class="form-row">${input('quantity','Quantity',t.quantity,'number','required min="0.001" max="1000000" step="any"')}${input('unit','Unit',t.unit,'text','maxlength="30" placeholder="pcs, kg, bottles…"')}</div><div class="form-row">${select('category','Category',CATEGORIES.map(c=>[c,c]),t.category)}${input('list','List',t.list,'text','required maxlength="80" list="shopping-lists"')}<datalist id="shopping-lists">${lists.map(l=>`<option value="${esc(l)}">`).join('')}</datalist></div>${select('placeId','Where to pick it up',[['','Any shop'],...store.list('place').map(r=>[r.id,r.data.title])],t.placeId)}<div class="form-row">${input('due','Needed by',t.due,'date')}${select('assignee','Who’s picking it up?',whoOptions(),t.assignee)}</div>${input('price',`Estimated price per ${esc(t.unit||'unit')} (${store.settings.currency})`,t.price,'number','required min="0" max="1000000" step="any"')}${textarea('notes','Notes / brand / alternatives',t.notes,'rows="3" maxlength="10000"')}<label class="check-label"><input name="favorite" type="checkbox" ${t.favorite?'checked':''}> Keep in favourites for easy re-shopping</label></fieldset>${store.canWrite?formFooter(id?'Save changes':'Add to basket',!!id):button('Close','close')}</form>`);
}
function noteEditor(id){const record=id?store.get(id):null;editing={kind:'note',id:id||uid(),data:record?.data||{title:'',body:'',pinned:false}};const n=editing.data;modal(id?'A note for us':'Leave a note',`<form id="note-form"><fieldset ${!store.canWrite?'disabled':''}>${input('title','Title',n.title,'text','required maxlength="200" autofocus')}${textarea('body','Your note',n.body,'rows="8" maxlength="20000"')}<label class="check-label"><input type="checkbox" name="pinned" ${n.pinned?'checked':''}> Pin to the top</label></fieldset>${store.canWrite?formFooter('Save note',!!id):button('Close','close')}</form>`);}
function placeEditor(id){const record=id?store.get(id):null;editing={kind:'place',id:id||uid(),data:record?.data||{title:'',address:'',lat:null,lon:null,notes:'',link:''}};const p=editing.data;modal(id?'Our saved place':'Save a place',`<form id="place-form"><fieldset ${!store.canWrite?'disabled':''}>${input('title','Place name',p.title,'text','required maxlength="200" autofocus')}${input('address','Address',p.address,'text','maxlength="500"')}<div class="button-row">${button('Find address on OpenStreetMap','search-place','secondary')}${button('Use my location','locate','secondary')}</div><p class="fine">Search opens OpenStreetMap in a new tab. Copy the latitude and longitude from its URL, or use your location while at the shop.</p><div class="form-row">${input('lat','Latitude',p.lat??'','number','min="-90" max="90" step="any" placeholder="52.5200"')}${input('lon','Longitude',p.lon??'','number','min="-180" max="180" step="any" placeholder="13.4050"')}</div>${input('link','Website',p.link,'url','maxlength="2000" placeholder="https://…"')}${textarea('notes','Useful things to know',p.notes,'rows="3" maxlength="10000" placeholder="Opening hours, our usual order…"')}</fieldset>${store.canWrite?formFooter('Save place',!!id):button('Close','close')}</form>`);}
function unlockVault(afterId=''){
  modal(store.list('secret').length?'Unlock our vault':'Choose our vault passphrase',`<form id="unlock-form" data-after="${esc(afterId)}"><p>Use a long, unique passphrase and share it privately with your partner. It is never sent to GitHub. Keep a safe copy; it cannot be recovered.</p>${input('passphrase','Vault passphrase','','password','required minlength="12" autocomplete="off" autofocus')}${!store.list('secret').length?input('confirm','Repeat passphrase','','password','required minlength="12" autocomplete="off"'):''}${formFooter('Unlock vault')}</form>`);
}
function lockVault(silent=false){const wasUnlocked=!!vaultPass;vaultPass='';clearTimeout(vaultTimer);if(editing?.kind==='secret')closeModal();if(page==='vault'&&(wasUnlocked||!silent))render();if(!silent)toast('Vault locked.');}
function touchVault(){if(!vaultPass)return;clearTimeout(vaultTimer);vaultTimer=setTimeout(()=>lockVault(),300000);}
async function secretEditor(id){
  if(!vaultPass)return unlockVault(id);
  const record=id?store.get(id):null;let value={value:'',notes:'',url:''};
  const pass=vaultPass;
  if(record)value=await decryptSecret(record.data.encrypted,pass,record.id);
  if(!vaultPass||vaultPass!==pass||document.hidden)return;
  editing={kind:'secret',id:id||uid(),data:record?.data||{title:''}};
  modal(id?'Your saved key':'Save a service key',`<form id="secret-form"><fieldset ${!store.canWrite?'disabled':''}>${input('title','Key name',editing.data.title,'text','required maxlength="200" autofocus placeholder="Maps API, personal AI key…"')}${input('value','API key / secret',value.value,'password','required maxlength="12000" autocomplete="off" spellcheck="false"')}</fieldset><div class="button-row">${button('Show / hide','reveal-secret','secondary')}${button(icon('copy')+'Copy key','copy-secret','secondary')}</div><fieldset ${!store.canWrite?'disabled':''}>${input('url','Service website',value.url,'url','maxlength="2000" placeholder="https://…"')}${textarea('notes','Private notes',value.notes,'rows="3" maxlength="10000"')}</fieldset><p class="fine">The key value, website and notes are encrypted with your vault passphrase. Its name is visible to household members.</p>${store.canWrite?formFooter('Encrypt & save',!!id):button('Close','close')}</form>`);touchVault();modalCleanup=()=>{value=null;editing=null;};
}
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function chooseFile(accept,callback){const input=document.createElement('input');input.type='file';input.accept=accept;input.onchange=async()=>{const file=input.files[0];if(!file)return;if(file.size>10000000)return toast('Please choose a file smaller than 10 MB.');try{await callback(await file.text());}catch(e){toast(e.message);}};input.click();}
let pendingImport=null;
function confirmImport(records){
  if(!store.canWrite)throw new Error('This key is read-only.');
  if(!records.length||records.length>1000)throw new Error('Import between 1 and 1,000 records at a time.');
  const ids=new Set();
  for(const r of records){if(!/^[a-zA-Z0-9_-]{8,80}$/.test(r.id)||ids.has(r.id)||(r.kind==='settings')!==(r.id==='household'))throw new Error('Invalid or duplicate record ID.');ids.add(r.id);r.data=validateRecord(r.kind,r.data);if(store.get(r.id)&&store.get(r.id).kind!==r.kind)throw new Error('A record ID belongs to a different type.');}
  pendingImport=records;
  const replaces=records.filter(r=>store.get(r.id)).length;
  modal('Review your import',`<p>Import <strong>${records.length}</strong> records. ${replaces} matching records will be updated. Other existing records will stay as they are.</p><p>Encrypted vault entries still require their original passphrase. Imported lists and places will be shared with your household.</p><div class="modal-actions">${button('Cancel','close')}${button('Import records','confirm-import','primary')}</div>`);
}
function githubHelp(){modal('Set up with two GitHub repositories',`<ol class="setup-steps"><li>Create a <strong>private</strong> data repository, such as <code>partner-data</code>, with a README and a <code>main</code> branch. Household files will be created under <code>together/</code>.</li><li>Publish only the <code>app/</code> folder in a separate public frontend repository, just like your todo app. Choose <strong>Settings → Pages → GitHub Actions</strong> there. Its included workflow also refreshes the public journey snapshot.</li><li>On GitHub, create two named fine-grained tokens. Select only the private data repository and grant <strong>Contents: Read and write</strong>. Create and revoke tokens in GitHub settings.</li><li>Connect each device using the same repository and branch, its own token, and a connection name. Save both tokens in your password manager.</li></ol><p class="fine">For independently owned fine-grained tokens, put the private repository in an organization with both of you as members. GitHub currently limits fine-grained tokens for outside collaborators. With two tokens created by one personal repository owner, both act as that owner.</p><p class="fine">Keep the data repository private. Photos and documents remain in Git history after removal from the app. Vault values additionally need your shared vault passphrase.</p><div class="button-row"><a class="primary" href="https://github.com/settings/personal-access-tokens/new" target="_blank" rel="noopener noreferrer">Create a GitHub token ↗</a>${button('Got it','close')}</div>`,true);}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied to clipboard.');}catch{toast('Clipboard unavailable. Select and copy the text manually.');}}
function navigate(next){location.hash=next;}
function saveEdit(data,message){const undo=store.change(editing.kind,editing.id,data);closeModal();toast(message,undo);}
function updateSubtask(id,fn){function walk(nodes){for(const n of nodes){if(n.id===id){fn(n);return true;}if(walk(n.children||[])){if(!(n.children||[]).every(c=>c.done))n.done=false;return true;}}return false;}walk(editing.data.children);}
function removeSubtask(id){function remove(nodes){return nodes.filter(n=>n.id!==id).map(n=>({...n,children:remove(n.children||[])}));}editing.data.children=remove(editing.data.children);}
function rerenderSubtasks(){$('#subtasks').innerHTML=subtasksHTML(editing.data.children);}
async function action(name,el){
  if(await household.action(name,el))return;
  const id=el?.dataset.id;
  if(name==='close')return closeModal();
  if(name==='nav')return navigate(el.dataset.page);
  if(name==='person-plans'){filter.assignee=el.dataset.person;filter.done=false;filter.search='';navigate(el.dataset.page);return;}
  if(name==='demo'){showLogin=false;store.startDemo();render();return;}
  if(name==='connect'){closeModal();showLogin=true;authError='';render();return;}
  if(name==='github-help')return githubHelp();
  if(name==='theme'){theme=theme==='light'?'dark':'light';writeLocal('theme',theme);document.documentElement.dataset.theme=theme;render();return;}
  if(name==='sync'){await store.sync();return;}
  if(name==='undo'){if(undoAction){const fn=undoAction;undoAction=null;fn();toast('Change undone.');}return;}
  if(name==='new-task')return taskEditor();if(name==='edit-task')return taskEditor(id);
  if(name==='new-item')return itemEditor();if(name==='edit-item')return itemEditor(id);
  if(name==='new-note')return noteEditor();if(name==='edit-note')return noteEditor(id);
  if(name==='new-place')return placeEditor();if(name==='edit-place')return placeEditor(id);
  if(name==='new-secret')return secretEditor();if(name==='edit-secret')return secretEditor(id);
  if(name==='toggle-task'){const r=store.get(id);if(!r)return;const undo=store.change(r.kind,r.id,completeTask(r.data));toast(r.data.repeat&&!r.data.done?'Done for now. The next occurrence is ready.':r.data.done?'To-do reopened.':'To-do completed.',undo);return;}
  if(name==='toggle-item'){const r=store.get(id);if(!r)return;const undo=store.change(r.kind,r.id,{...r.data,done:!r.data.done});toast(r.data.done?'Back on the shopping list.':'In the basket.',undo);return;}
  if(name==='add-subtask'){const title=$('#subtask-title').value.trim();if(!title)return;editing.data.children.push({...newTask(title),id:uid()});$('#subtask-title').value='';rerenderSubtasks();$('#subtask-title').focus();return;}
  if(name==='nested-subtask'){updateSubtask(id,n=>{n.children.push({...newTask('New step'),id:uid()});n.done=false;});rerenderSubtasks();return;}
  if(name==='remove-subtask'){removeSubtask(id);rerenderSubtasks();return;}
  if(name==='delete-record'){const target={...editing};modal('Delete this item?',`<p>“${esc(target.data.title)}” will be removed from your shared space.${target.kind==='task'?' Its subtasks will be removed too.':''}</p><div class="modal-actions">${button('Cancel','close')}${button('Delete item','confirm-delete','danger')}</div>`);editing=target;return;}
  if(name==='confirm-delete'){const undo=store.change(editing.kind,editing.id,{},true);closeModal();toast('Item deleted.',undo);return;}
  if(name==='shopping-list'){filter.list=el.dataset.list;render();return;}
  if(name==='copy-shopping'){const rows=store.list('item').filter(matches).filter(r=>(filter.list==='all'||r.data.list===filter.list)&&(filter.place==='all'||r.data.placeId===filter.place)&&(!filter.favorites||r.data.favorite));return copy(rows.map(r=>`${r.data.done?'☑':'☐'} ${r.data.quantity} ${r.data.unit} ${r.data.title}${r.data.placeId?' — '+(store.get(r.data.placeId)?.data.title||''):''}`).join('\n'));}
  if(name==='reset-shopping'){chooseBoughtItems();return;}
  if(name==='prev-month'||name==='next-month'){const d=parseDate(calendarMonth+'-01');d.setMonth(d.getMonth()+(name==='next-month'?1:-1));calendarMonth=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;render();return;}
  if(name==='today-month'){calendarMonth=today().slice(0,7);render();return;}
  if(name==='day-events'){const rows=store.records.filter(r=>r.kind==='appointment'?household.appointmentOnDate(r.data,el.dataset.date):['task','item'].includes(r.kind)&&r.data.due===el.dataset.date&&!r.data.done);modal(dueLabel(el.dataset.date),rows.map(r=>r.kind==='appointment'?household.appointmentRow(r):r.kind==='task'?taskRow(r):itemRow(r)).join(''),true);return;}
  if(name==='select-place'){selectedPlace=id;render();return;}
  if(name==='allow-map'||name==='disable-map'){mapAllowed=name==='allow-map';writeLocal('mapConsent',mapAllowed);render();return;}
  if(name==='search-place'){const form=$('#place-form'),address=form.elements.address.value||form.elements.title.value;if(!address.trim())throw new Error('Enter an address or place name first.');window.open('https://www.openstreetmap.org/search?query='+encodeURIComponent(address),'_blank','noopener,noreferrer');return;}
  if(name==='locate'){if(!navigator.geolocation)throw new Error('Location is not supported on this device.');const form=$('#place-form');el.disabled=true;try{const p=await new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(resolve,reject,{enableHighAccuracy:true,timeout:15000,maximumAge:60000}));if(form.isConnected){form.elements.lat.value=p.coords.latitude.toFixed(6);form.elements.lon.value=p.coords.longitude.toFixed(6);}}catch{throw new Error('Could not get your location. Allow location access, or enter coordinates manually.');}finally{el.disabled=false;}return;}
  if(name==='unlock-vault')return unlockVault(id||'');if(name==='lock-vault')return lockVault();
  if(name==='reveal-secret'){const input=$('[name="value"]');input.type=input.type==='password'?'text':'password';return;}
  if(name==='copy-secret')return copy($('[name="value"]').value);
  if(name==='export-md')return download('todo.md',exportMarkdown(store.list('task').map(r=>r.data)),'text/markdown');
  if(name==='export-calendar')return download('together.ics',calendarExport(store.records),'text/calendar');
  if(name==='export-backup')return download(`together-${today()}.json`,JSON.stringify({format:'together-backup',version:1,exportedAt:new Date().toISOString(),records:store.records},null,2),'application/json');
  if(name==='import-md')return chooseFile('.md,.txt',text=>confirmImport(importMarkdown(text).map(data=>({id:uid(),kind:'task',data}))));
  if(name==='import-backup')return chooseFile('.json',text=>{const backup=JSON.parse(text);if(backup.format!=='together-backup'||backup.version!==1||!Array.isArray(backup.records))throw new Error('This is not a supported Together backup.');confirmImport(backup.records.filter(r=>!r.deleted));});
  if(name==='confirm-import'){const records=pendingImport;pendingImport=null;for(const r of records)store.change(r.kind,r.id,r.data);closeModal();toast(`Imported ${records.length} records.`);return;}
  if(name==='compare-conflict'){const c=store.conflict;const safe=r=>r?.kind==='secret'?{title:r.data?.title,note:'Encrypted vault contents are not displayed.'}:r?.data||'(deleted)';modal('Review both versions',`<div class="compare-grid"><section><h3>Your edit</h3><pre>${esc(JSON.stringify(safe(c.op),null,2))}</pre></section><section><h3>The GitHub version</h3><pre>${esc(JSON.stringify(safe(c.current),null,2))}</pre></section></div><div class="modal-actions">${button('Use their version','use-theirs')}${button('Keep my version','keep-mine','primary')}</div>`,true);return;}
  if(name==='use-theirs'||name==='keep-mine'){store.resolve(name==='keep-mine');closeModal();return;}
  if(name==='logout'){if(store.pending.length){modal('Changes are still on this device',`<p>You have ${store.pending.length} unsynced changes. Sync or export a backup before forgetting this device. Discarding removes those local changes.</p><div class="button-stack">${button('Keep working','close','primary')}${button('Export backup','export-backup')}${button('Discard local changes & log out','confirm-logout','danger')}</div>`);return;}return action('confirm-logout');}
  if(name==='confirm-logout'){household.clear();closeModal();vaultPass='';clearTimeout(vaultTimer);showLogin=true;authError='';store.disconnect();forgetCredentials();render();return;}
  if(name==='more'){modal('Browse',`<div class="browse-grid">${[...nav.filter(n=>['appointments','documents','damages','places','vault'].includes(n[0])),['settings','Settings']].map(([p,l])=>button(`<span class="browse-icon">${icon(p)}</span><span>${l}</span>${icon('arrow')}`,'mobile-nav',`browse-link ${page===p?'active':''}`,`data-page="${p}" ${page===p?'aria-current="page"':''}`)).join('')}</div>`);return;}
  if(name==='quick-create'){modal('Add to your space',`<div class="browse-grid">${[['tasks','To-do','new-task'],['shopping','Shopping item','new-item'],['appointments','Appointment','new-appointment'],['documents','Document','new-document'],['damages','Damage photo','new-damage'],['note','Note','new-note']].map(([i,l,a])=>button(`<span class="browse-icon">${icon(i)}</span><span>${l}</span>`,'create-entry','browse-link',`data-create="${a}"`)).join('')}</div>`);return;}
  if(name==='create-entry'){closeModal();await action(el.dataset.create);return;}
  if(name==='mobile-nav'){closeModal();navigate(el.dataset.page);return;}
  if(name==='install'){if(window.matchMedia('(display-mode: standalone)').matches)return toast('Together is already running as an installed app.');if(installPrompt){await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;}else modal('Take Together with you',`<div class="install-guide"><p><strong>Android · Google Chrome</strong><br>Open the hosted HTTPS website in Chrome, tap the ⋮ menu, then <strong>Install app</strong> or <strong>Add to Home screen</strong>.</p><p><strong>iPhone / iPad</strong><br>Open the website in Safari, tap Share, then <strong>Add to Home Screen</strong>.</p><p><strong>Desktop Chrome</strong><br>Use the install icon in the address bar or the browser menu.</p><p class="fine">Connect inside the installed app if it uses separate storage. First load needs a connection; your cached lists then work offline.</p>${button('Got it','close','primary')}</div>`);return;}
  if(name==='update'){if(store.pending.length)throw new Error('Sync or export your waiting changes before updating.');updateWorker?.postMessage('SKIP_WAITING');return;}
  if(name==='all-notes'){modal('All our notes',`<div class="note-grid">${store.list('note').map(r=>`<button class="note-card" data-action="edit-note" data-id="${r.id}"><h3>${esc(r.data.title)}</h3><p>${esc(r.data.body)}</p></button>`).join('')}</div>`,true);return;}
}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el||el.disabled)return;event.preventDefault();Promise.resolve(action(el.dataset.action,el)).catch(formError);});
document.addEventListener('input',event=>{
  if(event.target.id==='search'){filter.search=event.target.value;render();}
  if(event.target.dataset.subtitle&&editing?.kind==='task')updateSubtask(event.target.dataset.subtitle,n=>n.title=event.target.value);
});
document.addEventListener('change',event=>{
  const el=event.target;
  if(el.matches('#repick-form input[name=item]')){const count=$('#repick-form').querySelectorAll('input[name=item]:checked').length;$('#repick-count').textContent=count+' selected';const submit=$('#repick-form button[type=submit]');submit.disabled=!count;submit.textContent=count?`Uncheck selected (${count})`:'Uncheck selected';}
  if(el.dataset.filter){filter[el.dataset.filter]=el.type==='checkbox'?el.checked:el.value;render();}
  if(el.dataset.subtask&&editing?.kind==='task'){updateSubtask(el.dataset.subtask,n=>{n.done=el.checked;n.children=checkChildren(n.children||[],n.done);});rerenderSubtasks();}
});
document.addEventListener('submit',async event=>{
  event.preventDefault();const form=event.target;if(busy)return;const data=Object.fromEntries(new FormData(form));busy=true;setBusy(form,true);$('.form-error',form)?.replaceChildren();
  try{
    if(await household.submit(form,data))return;
    if(form.id==='repick-form'){
      if(!shoppingSelection||shoppingSelection.generation!==store.generation)throw new Error('Connection changed. Reopen the item picker.');
      if(!store.canWrite)throw new Error('This connection is read-only.');
      const ids=[...new FormData(form).getAll('item')].filter(id=>shoppingSelection.ids.has(id));
      if(!ids.length)throw new Error('Choose at least one item.');
      const rows=ids.map(id=>store.get(id)).filter(r=>r?.kind==='item'&&r.data.done),undo=[];
      for(const r of rows)undo.push(store.change('item',r.id,{...r.data,done:false}));
      closeModal();toast(rows.length?`${rows.length} item${rows.length===1?'':'s'} returned to your list.`:'These items are already unchecked.',undo.length?()=>undo.forEach(fn=>fn()):null);
    }else if(form.id==='connect-form'){
      const config={repo:data.repo,branch:data.branch,label:data.label,token:data.token.trim(),readOnly:!!data.readOnly};household.clear();lockVault(true);await store.connect(config);saveCredentials(config,!!data.remember);showLogin=false;authError='';render();
    }else if(form.id==='quick-task'){
      const parsed=quickParse(data.title);if(!parsed.title)throw new Error('Give your to-do a title.');const undo=store.change('task',uid(),{...newTask(),...parsed});toast('Added to our to-dos.',undo);form.reset();render();$('#quick-task input')?.focus();
    }else if(form.id==='quick-item'){
      const undo=store.change('item',uid(),{...newItem(data.title),list:filter.list==='all'?'Groceries':filter.list});toast('Added to our basket.',undo);form.reset();render();$('#quick-item input')?.focus();
    }else if(form.id==='task-form'){
      const parsed=quickParse(data.title),tags=[...new Set([...data.tags.split(',').map(t=>t.trim()).filter(Boolean),...parsed.tags])];
      const children=editing.data.children,hasOpen=flattenChildren(children).some(c=>!c.done);
      saveEdit({...editing.data,...parsed,due:parsed.due||data.due,priority:parsed.priority||Number(data.priority),tags,assignee:data.assignee,repeat:data.repeat,notes:data.notes,link:data.link,done:hasOpen?false:editing.data.done},'To-do saved.');
    }else if(form.id==='item-form')saveEdit({...editing.data,...data,quantity:Number(data.quantity),price:Number(data.price),favorite:!!data.favorite},'Shopping item saved.');
    else if(form.id==='note-form')saveEdit({title:data.title,body:data.body,pinned:!!data.pinned},'Note saved.');
    else if(form.id==='place-form')saveEdit({...data,lat:data.lat===''?null:Number(data.lat),lon:data.lon===''?null:Number(data.lon)},'Place saved.');
    else if(form.id==='household-form'){store.change('settings','household',{...data,budget:Number(data.budget)});toast('Settings saved.');render();}
    else if(form.id==='unlock-form'){
      if(data.confirm!==undefined&&data.confirm!==data.passphrase)throw new Error('The two passphrases do not match.');
      const first=store.get(form.dataset.after)||store.list('secret')[0];if(first)await decryptSecret(first.data.encrypted,data.passphrase,first.id);
      if(document.hidden)throw new Error('Return to the app to unlock your vault.');
      vaultPass=data.passphrase;touchVault();const after=form.dataset.after;closeModal();render();if(after)await secretEditor(after);
    }else if(form.id==='secret-form'){
      if(!vaultPass)throw new Error('Unlock your vault again.');
      const target=editing,pass=vaultPass;const encrypted=await encryptSecret({value:data.value,notes:data.notes,url:data.url},pass,target.id);
      if(!vaultPass||editing!==target)throw new Error('Vault locked. Unlock it again to save.');saveEdit({title:data.title,encrypted},'Key encrypted and saved.');
    }
  }catch(e){if(form.id==='connect-form'){authError=e.message;showLogin=true;render();}else{const error=$('.form-error',form);if(error&&form.isConnected)error.textContent=e.message;else formError(e);}}
  finally{busy=false;setBusy(form,false);}
});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);page=[...nav.map(n=>n[0]),'settings'].includes(next)?next:'home';filter.search='';render();window.scrollTo({top:0});$('#main')?.focus({preventScroll:true});});
document.addEventListener('keydown',event=>{
  touchVault();if(event.target.id==='subtask-title'&&event.key==='Enter'){event.preventDefault();action('add-subtask');return;}
  if(event.target.matches('input,textarea,select')||$('#modal').open||event.ctrlKey||event.metaKey||event.altKey)return;
  if(event.key==='/') {event.preventDefault();$('#search')?.focus();}
  if(event.key.toLowerCase()==='n'&&!showLogin&&store.canWrite){event.preventDefault();action(page==='shopping'?'new-item':page==='places'?'new-place':page==='vault'?'new-secret':page==='damages'?'new-damage':page==='documents'?'new-document':['appointments','calendar'].includes(page)?'new-appointment':'new-task').catch(formError);}
});
document.addEventListener('pointerdown',touchVault,{passive:true});
document.addEventListener('visibilitychange',()=>{if(document.hidden)lockVault(true);else if(!showLogin)store.sync();});
window.addEventListener('online',()=>{if(!showLogin)store.sync();});
window.addEventListener('offline',()=>{if(!store.demo&&!showLogin){store.state='offline';render();}});
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;});
window.addEventListener('appinstalled',()=>{installPrompt=null;toast('Together is ready on your home screen.');});
store.addEventListener('change',()=>{
  if(store.state==='locked'){household.clear();vaultPass='';closeModal();showLogin=true;authError=store.error;}
  const drafting=document.activeElement?.closest('#main form');
  if(!drafting||store.state==='locked'||store.state==='conflict')render();
});
setInterval(()=>{if(!document.hidden&&!showLogin)store.sync();},60000);
let swReloading=false;
if('serviceWorker' in navigator){
  navigator.serviceWorker.register('./sw.js').then(reg=>{
    if(reg.waiting){updateWorker=reg.waiting;render();}
    reg.addEventListener('updatefound',()=>{const worker=reg.installing;worker.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller){updateWorker=worker;render();}});});
  }).catch(()=>toast('Offline app installation is unavailable in this browser.'));
  navigator.serviceWorker.addEventListener('controllerchange',()=>{if(updateWorker&&!swReloading){swReloading=true;location.reload();}});
}
render();
const saved=credentials();
if(saved?.token){showLogin=false;store.connect(saved,{verify:false}).then(()=>{if(store.state==='locked'||!store.key){showLogin=true;authError=store.error||'Connect to GitHub once before using offline mode.';}render();}).catch(e=>{showLogin=true;authError=e.message;render();});}
